from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    singleton = set()
    for r in range(h):
        for c in range(w):
            if (r,c) in seen:
                continue
            color = grid[r][c]
            q = [(r,c)]
            seen.add((r,c))
            comp = []
            while q:
                y,x = q.pop()
                comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); q.append((ny,nx))
            if len(comp)==1 and color != bg:
                singleton.add((r,c))
    guesses={}
    for r,c in singleton:
        adjacent=Counter()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dy,c+dx
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in singleton:
                adjacent[grid[nr][nc]] += 1
        choices=[(n,v) for v,n in adjacent.items() if n>=2]
        if choices:
            best=max(n for n,v in choices)
            tied=[v for n,v in choices if n==best]
            color=next((v for v in tied if v != bg), bg)
        else:
            color=bg
        guesses[(r,c)]=color
    out=[row[:] for row in grid]
    for r,c in singleton:
        color=guesses[(r,c)]
        if color != bg:
            seeds=[(r+dy,c+dx) for dy,dx in ((1,0),(-1,0),(0,1),(0,-1))
                   if 0<=r+dy<h and 0<=c+dx<w and
                   (grid[r+dy][c+dx]==color or guesses.get((r+dy,c+dx))==color)]
            region=set(seeds); stack=seeds[:]
            while stack:
                y,x=stack.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (grid[yy][xx]==color or guesses.get((yy,xx))==color) and (yy,xx) not in region:
                        region.add((yy,xx)); stack.append((yy,xx))
            region.add((r,c))
            rs=[y for y,x in region]; cs=[x for y,x in region]
            if (max(rs)-min(rs)+1)*(max(cs)-min(cs)+1) != len(region):
                color=bg
        out[r][c]=color
    return out

